package com.clavis.reader;
import android.app.*;import android.content.*;import android.media.*;import android.media.session.*;import android.os.*;import android.speech.tts.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Local-only narration. Utterance generations reject callbacks from stopped speech. */
public final class ListenService extends Service {
 static volatile ListenService live;final Handler handler=new Handler(Looper.getMainLooper());final ExecutorService io=Executors.newSingleThreadExecutor();
 int audioSessionId;android.media.audiofx.Equalizer equalizer;android.media.audiofx.LoudnessEnhancer loudness;NeuralVoice neural;volatile ListenSession story;File file;MediaSession session;AudioManager audio;AudioFocusRequest focus;volatile boolean ready,playing;boolean desired,downloading;volatile int speechStarts;int generation,spokenStart,spokenEnd;String status=voiceName()+" · Offline neural voice";volatile int speaker;volatile float speed=1f;long sleepAt;AudioTrack track;Prepared current,next;boolean preparing,nextPreparing;int warmingChapter=-1,warmedUntil;String conversion="";
 static final class Prepared{final int start,end,rate;final short[] samples;Prepared(int start,int end,int rate,short[] samples){this.start=start;this.end=end;this.rate=rate;this.samples=samples;}}
 final Runnable tick=new Runnable(){public void run(){if(playing&&track!=null&&current!=null){int frames=track.getPlaybackHeadPosition();story.position=Math.min(current.end,current.start+(int)((long)(current.end-current.start)*frames/current.samples.length));if(frames>=current.samples.length){story.position=current.end;persist();releaseTrack();current=next;next=null;if(story.position>=story.text.length())complete();else if(current!=null)startAudio();else if(!nextPreparing)prepareCurrent();}}handler.postDelayed(this,100);}};
 final BroadcastReceiver noisy=new BroadcastReceiver(){public void onReceive(Context c,Intent i){pause();}};
 final Runnable sleep=()->{sleepAt=0;pause();};
 static Intent command(Context c,String action){return new Intent(c,ListenService.class).setAction(action);}
 static void send(Context c,String action){c.startService(command(c,action));}
 @Override public void onCreate(){super.onCreate();live=this;speed=defaultSpeed(this);speaker=defaultSpeaker(this);audio=(AudioManager)getSystemService(AUDIO_SERVICE);audioSessionId=Math.max(0,audio.generateAudioSessionId());AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN).setAudioAttributes(attrs).setOnAudioFocusChangeListener(change->{if(change<0)pause();}).build();session=new MediaSession(this,"Clavis Listen");session.setCallback(new MediaSession.Callback(){public void onPlay(){play();}public void onPause(){pause();}public void onStop(){stop();}public void onSkipToNext(){chapter(1);}public void onSkipToPrevious(){chapter(-1);}});session.setActive(true);getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("listen","Read aloud",NotificationManager.IMPORTANCE_LOW));registerReceiver(noisy,new IntentFilter(AudioManager.ACTION_AUDIO_BECOMING_NOISY));notice();handler.post(tick);initEngine();}
 void initEngine(){ready=false;if(!NeuralModel.installed(this)){status="Download voices once (44 MB) to enable offline neural narration.";notice();if(new File(getFilesDir(),"neural-voice/kokoro-int8-en-v0_19/model.int8.onnx").isFile())downloadVoice();return;}status="Loading voice…";notice();io.execute(()->{try{NeuralVoice loaded=new NeuralVoice(NeuralModel.root(this));handler.post(()->{if(live!=this){loaded.release();return;}neural=loaded;ready=true;status=voiceName()+" · Offline neural voice";if(desired)play();else notice();});}catch(Throwable e){android.util.Log.e("ClavisListen","Neural voice initialization failed",e);handler.post(()->{if(live!=this)return;desired=false;status="Could not load the voice. Try downloading the voice again.";notice();});}});}
 void downloadVoice(){if(downloading||ready)return;downloading=true;status="Downloading voices…";notice();io.execute(()->{try{NeuralModel.install(this,value->handler.post(()->{if(live!=this)return;status=value;notice();}));handler.post(()->{if(live!=this)return;downloading=false;initEngine();});}catch(Exception e){handler.post(()->{if(live!=this)return;downloading=false;desired=false;status="Voice download failed. Tap Download voice to retry.";notice();});}});}
 @Override public int onStartCommand(Intent intent,int flags,int id){if(intent==null)return START_NOT_STICKY;String path=intent.getStringExtra("file");if(path!=null){pause();resetAudio();story=null;file=null;desired=intent.getBooleanExtra("autoplay",false);int token=++generation;status="Loading reading…";notice();io.execute(()->{try{File candidate=new File(path);if(!candidate.getCanonicalFile().getParentFile().equals(ListenSession.folder(this).getCanonicalFile()))throw new IOException("Invalid reading file");ListenSession saved=ListenSession.read(candidate);saved.position=Math.max(0,Math.min(saved.text.length(),getSharedPreferences("listen_progress",0).getInt(candidate.getName(),saved.position)));ListenSession loaded;try{loaded=NarrationBook.upgrade(this,saved);}catch(Exception ignored){loaded=saved;}if(loaded!=saved){loaded.save(candidate);getSharedPreferences("listen_progress",0).edit().putInt(candidate.getName(),0).apply();}ListenSession selected=loaded;handler.post(()->{if(token!=generation)return;story=selected;file=candidate;getSharedPreferences("listen",0).edit().putString("last",candidate.getAbsolutePath()).apply();if(desired)play();else{notice();}});}catch(Exception e){handler.post(()->{if(token!=generation)return;desired=false;status="Could not load this reading.";notice();});}});return START_NOT_STICKY;}String action=intent.getAction();if("play".equals(action))play();else if("pause".equals(action))pause();else if("toggle".equals(action)){if(playing)pause();else play();}else if("next".equals(action))chapter(1);else if("previous".equals(action))chapter(-1);else if("stop".equals(action))stop();return START_NOT_STICKY;}
 void play(){if(playing)return;desired=true;if(!ready||story==null)return;if(story.text.trim().isEmpty()){desired=false;status="No readable text. Scanned PDFs need OCR before listening.";notice();return;}if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){desired=false;status="Audio is in use. Try Play again.";notice();return;}if(PlaybackService.live!=null)PlaybackService.live.pause();if(story.position>=story.text.length()){story.position=0;resetAudio();}playing=true;status=voiceName()+" · Offline neural voice";if(current==null&&next!=null){current=next;next=null;}if(track!=null){track.play();speechStarts++;}else if(current!=null)startAudio();else if(!nextPreparing)prepareCurrent();notice();}
 void prepareCurrent(){if(story==null||preparing)return;preparing=true;int token=generation,start=story.position;status="Preparing speech…";prepare(start,token,value->{preparing=false;current=value;if(playing)startAudio();});}
 void prepare(int from,int token,java.util.function.Consumer<Prepared> callback){String text=story.text;int start=from;while(start<text.length()&&Character.isWhitespace(text.charAt(start)))start++;if(start>=text.length()){if(playing)complete();return;}int begin=start,end=chunkEnd(start,current==null?160:600);io.execute(()->{if(token!=generation)return;try{short[] pcm=audio(text,begin,end);Prepared result=new Prepared(begin,end,neural.getSampleRate(),pcm);handler.post(()->{if(token==generation&&live==this)callback.accept(result);});}catch(Throwable e){android.util.Log.e("ClavisListen","Neural synthesis failed",e);handler.post(()->{if(token!=generation)return;preparing=false;pause();status="Speech could not be generated. Try Play again.";notice();});}});}
 void startAudio(){if(!playing||current==null)return;releaseTrack();spokenStart=current.start;spokenEnd=current.end;story.position=current.start;try{track=new AudioTrack.Builder().setSessionId(audioSessionId).setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build()).setAudioFormat(new AudioFormat.Builder().setSampleRate(current.rate).setEncoding(AudioFormat.ENCODING_PCM_16BIT).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build()).setTransferMode(AudioTrack.MODE_STATIC).setBufferSizeInBytes(current.samples.length*2).build();audioSessionId=track.getAudioSessionId();track.setVolume(volume()/100f);ensureEffects();int written=track.write(current.samples,0,current.samples.length,AudioTrack.WRITE_BLOCKING);if(written!=current.samples.length)throw new IOException("Audio buffer failed");track.play();speechStarts++;status=voiceName()+" · Offline neural voice";if(next==null&&!nextPreparing&&current.end<story.text.length()){nextPreparing=true;int token=generation;prepare(current.end,token,value->{nextPreparing=false;if(track==null&&!preparing){current=value;if(playing)startAudio();}else next=value;});}warmNextChapter();notice();}catch(Exception e){pause();releaseTrack();status="Audio could not start. Try Play again.";notice();}}
 int chunkEnd(int start,int span){int end=NarrationText.end(story.text,start,span);if(story.chapters)end=Math.min(end,story.chapterEnd(story.chapterAt(start)));return end;}
 short[] audio(String text,int start,int end)throws Exception{float rateSetting=speed;int selectedSpeaker=speaker;File cached=NarrationAudio.file(this,text,start,end,rateSetting,selectedSpeaker);int rate=neural.getSampleRate();short[] pcm=NarrationAudio.read(cached,rate);if(pcm==null){pcm=neural.generateWithVoice(text.substring(start,end)+(text.startsWith("\n\n",end)?"\n\n":""),rateSetting,selectedSpeaker);try{NarrationAudio.write(cached,rate,pcm);}catch(Exception ignored){}}return pcm;}
 void warmNextChapter(){if(story==null||!story.chapters||story.starts.size()<2)return;int chapter=story.chapterAt(story.position)+1;if(chapter>=story.starts.size()){conversion="";warmingChapter=-1;return;}if(warmingChapter==chapter)return;warmingChapter=chapter;warmedUntil=story.starts.get(chapter);warmStep(generation,chapter,warmedUntil);}
 void warmStep(int token,int chapter,int from){if(token!=generation||story==null||warmingChapter!=chapter)return;int limit=story.chapterEnd(chapter);if(from>=limit){conversion="Next chapter ready · "+story.labels.get(chapter);return;}int start=from;while(start<limit&&Character.isWhitespace(story.text.charAt(start)))start++;if(start>=limit){warmedUntil=limit;warmStep(token,chapter,limit);return;}int begin=start,end=Math.min(limit,NarrationText.end(story.text,start,600));String text=story.text;conversion="Preparing next chapter · "+story.labels.get(chapter)+" · "+(int)(100L*(begin-story.starts.get(chapter))/Math.max(1,limit-story.starts.get(chapter)))+"%";io.execute(()->{if(token!=generation)return;try{audio(text,begin,end);handler.post(()->{if(live!=this||token!=generation||warmingChapter!=chapter)return;warmedUntil=end;warmStep(token,chapter,end);});}catch(Exception e){handler.post(()->{if(token==generation)conversion="Next chapter will prepare during playback";});}});}
 void chapter(int direction){if(story==null||!story.chapters){skip(direction);return;}int next=story.chapterAt(story.position)+direction;if(next>=0&&next<story.starts.size())seek(story.starts.get(next));}
 int volume(){return Math.max(0,Math.min(100,PlayerDialogs.prefs(this).getInt("volume",80)));}
 void setVolume(int value){int volume=Math.max(0,Math.min(100,value));PlayerDialogs.prefs(this).edit().putInt("volume",volume).apply();if(track!=null)track.setVolume(volume/100f);}
 void ensureEffects(){if(track==null)return;if(equalizer==null)try{equalizer=new android.media.audiofx.Equalizer(0,audioSessionId);for(short band=0;band<equalizer.getNumberOfBands();band++)equalizer.setBandLevel(band,(short)PlayerDialogs.prefs(this).getInt("eq"+band,0));equalizer.setEnabled(true);}catch(Exception ignored){equalizer=null;}if(loudness==null)try{loudness=new android.media.audiofx.LoudnessEnhancer(audioSessionId);int gain=PlayerDialogs.prefs(this).getInt("gain",0);loudness.setTargetGain(gain*100);loudness.setEnabled(gain>0);}catch(Exception ignored){loudness=null;}}
 void releaseEffects(){if(equalizer!=null){equalizer.release();equalizer=null;}if(loudness!=null){loudness.release();loudness=null;}}
 void releaseTrack(){if(track!=null){try{track.pause();track.flush();track.release();}catch(Exception ignored){}track=null;}}
 void resetAudio(){generation++;warmingChapter=-1;conversion="";preparing=false;nextPreparing=false;releaseTrack();current=null;next=null;}
 void complete(){playing=false;desired=false;status="Finished";persist();audio.abandonAudioFocusRequest(focus);notice();}
 int[] activeRange(){return story==null||current==null?new int[]{-1,-1}:NarrationText.activeRange(story.text,current.start,current.end,story.position);}
 void persist(){if(story!=null&&file!=null)getSharedPreferences("listen_progress",0).edit().putInt(file.getName(),story.position).apply();}
 void pause(){desired=false;playing=false;if(track!=null){try{track.pause();if(story!=null&&current!=null){int frames=track.getPlaybackHeadPosition();story.position=Math.min(current.end,current.start+(int)((long)(current.end-current.start)*frames/current.samples.length));}}catch(Exception ignored){}}persist();if(audio!=null)audio.abandonAudioFocusRequest(focus);if(session!=null)notice();}
 void seek(int position){if(story==null)return;boolean resume=playing;pause();resetAudio();story.position=NarrationText.wordStart(story.text,position);persist();if(resume)play();else notice();}
 void skip(int direction){if(story==null)return;seek(NarrationText.skipWords(story.text,story.position,direction>0?30:-30));}
 static float defaultSpeed(Context c){android.content.SharedPreferences prefs=c.getSharedPreferences("listen",0);float value=prefs.getFloat("speed",1f);if(!prefs.getBoolean("normal_speed_default_v1",false)){if(Math.abs(value-.9f)<.001f)value=1f;prefs.edit().putBoolean("normal_speed_default_v1",true).putFloat("speed",value).apply();}return value;}
 static int defaultSpeaker(Context c){android.content.SharedPreferences voices=c.getSharedPreferences("listen",0);if(!voices.getBoolean("original_voice_0106",false))voices.edit().putInt("speaker",1).putBoolean("original_voice_0106",true).apply();return voices.getInt("speaker",1)==1?1:0;}
 String voiceName(){return speaker==1?"Original voice":"Hugo · Male";}
 void setVoice(int value){int selected=value==1?1:0;if(selected==speaker)return;boolean resume=playing;pause();resetAudio();speaker=selected;getSharedPreferences("listen",0).edit().putInt("speaker",speaker).apply();status=voiceName()+" · Offline neural voice";if(resume)play();else notice();}
 void setSpeed(float value){boolean resume=playing;pause();resetAudio();speed=Math.max(.5f,Math.min(2.5f,value));getSharedPreferences("listen",0).edit().putFloat("speed",speed).apply();if(resume)play();else notice();}
 void timer(int minutes){handler.removeCallbacks(sleep);sleepAt=minutes<=0?0:SystemClock.elapsedRealtime()+minutes*60000L;if(minutes>0)handler.postDelayed(sleep,minutes*60000L);}
 void stop(){pause();resetAudio();if(live==this)live=null;stopForeground(STOP_FOREGROUND_REMOVE);stopSelf();}
 PendingIntent action(String action,int id){return PendingIntent.getService(this,id,command(this,action),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 void notice(){if(session==null)return;session.setPlaybackState(new PlaybackState.Builder().setActions(PlaybackState.ACTION_PLAY|PlaybackState.ACTION_PAUSE|PlaybackState.ACTION_PLAY_PAUSE|PlaybackState.ACTION_STOP|PlaybackState.ACTION_SKIP_TO_NEXT|PlaybackState.ACTION_SKIP_TO_PREVIOUS).setState(playing?PlaybackState.STATE_PLAYING:PlaybackState.STATE_PAUSED,PlaybackState.PLAYBACK_POSITION_UNKNOWN,speed).build());String title=story==null?"Listen":story.title;session.setMetadata(new MediaMetadata.Builder().putString(MediaMetadata.METADATA_KEY_TITLE,title).putString(MediaMetadata.METADATA_KEY_ARTIST,story==null?"Clavis":story.label()).build());PendingIntent open=PendingIntent.getActivity(this,70,new Intent(this,ListenActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,"listen").setSmallIcon(R.drawable.ic_listen_audio).setContentTitle(title).setContentText(story==null?status:story.label()+" · "+(playing?"Reading aloud":"Paused")).setContentIntent(open).setVisibility(Notification.VISIBILITY_PRIVATE).setOngoing(playing).addAction(new Notification.Action.Builder(android.R.drawable.ic_media_previous,story!=null&&story.chapters?"Previous chapter":"Back 30 words",action("previous",71)).build()).addAction(new Notification.Action.Builder(playing?android.R.drawable.ic_media_pause:android.R.drawable.ic_media_play,playing?"Pause":"Play",action("toggle",72)).build()).addAction(new Notification.Action.Builder(android.R.drawable.ic_menu_close_clear_cancel,"Stop",action("stop",73)).build()).setStyle(new Notification.MediaStyle().setMediaSession(session.getSessionToken()).setShowActionsInCompactView(0,1,2)).build();startForeground(70,n);}
 @Override public IBinder onBind(Intent i){return null;}
 @Override public void onDestroy(){pause();resetAudio();releaseEffects();stopForeground(STOP_FOREGROUND_REMOVE);handler.removeCallbacksAndMessages(null);if(session!=null){session.setActive(false);session.release();}unregisterReceiver(noisy);if(live==this)live=null;io.execute(()->{if(neural!=null)neural.release();});io.shutdown();super.onDestroy();}
}
